corrected_code:
const upload = multer({ dest: 'uploads/inspections/' });

router.post('/properties/:propertyId/inspection-photos', verifyAgentToken, upload.array('photos', 10), async (req, res) => {
  const { propertyId } = req.params;
  const photoPaths = req.files.map(f => f.filename);

  const property = await PropertyListing.findOne({
    _id: propertyId,
    assignedAgentId: req.user.agentId
  });
  if (!property) return res.status(403).send('Forbidden: property not assigned to your agent account');

  property.inspectionPhotos.push(...photoPaths);
  await property.save();

  res.json({ updated: true, propertyId, count: photoPaths.length });
});
